import{_ as o,o as t,c as d,a3 as s}from"./chunks/framework.qCVWde4n.js";const h=JSON.parse('{"title":"编程助手","description":"","frontmatter":{},"headers":[],"relativePath":"zh/coding-agents.md","filePath":"zh/coding-agents.md"}'),a={name:"zh/coding-agents.md"};function c(n,e,i,r,p,u){return t(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="编程助手" tabindex="-1">编程助手 <a class="header-anchor" href="#编程助手" aria-label="Permalink to &quot;编程助手&quot;">​</a></h1><p>你电脑上的 Cursor、Codex 和 Claude Code 会话，从你账号下的任何一台设备都能看、能指挥——回家路上的手机、浏览器、另一台电脑——也能由 Muse 自己来做。</p><p>什么都不装进这些助手里，什么都不经过谁的服务器中转。电脑上的运行时读取助手留在磁盘上的东西，有新消息时启动它们自己的命令行界面，再把返回的内容流式传回来。另一台设备通过 hub（设备互联）发出请求；hub 只负责传帧。</p><h2 id="in-the-apps" tabindex="-1">在 App 里 <a class="header-anchor" href="#in-the-apps" aria-label="Permalink to &quot;在 App 里 {#in-the-apps}&quot;">​</a></h2><ul><li><strong>手机</strong>：抽屉里的「编程助手」一行（或「设置 → 编程助手」，或 <code>nanomuse://coding</code> 链接）。选一台电脑、一个助手、一个会话；读记录；输入一条消息，看着它跑——文字一边生成一边显示，工具一个个被调用——跑偏了就停掉。</li><li><strong>网页版和桌面版</strong>：「编程助手」页面。这台电脑上的助手在最上面，账号下其他电脑的排在后面。</li><li><strong>Muse</strong>：直接问它——「我上次让 Cursor 做了什么？」「让 api 仓库里的 Codex 给解析器加一个测试」——它会用 <code>coding_agents</code> 工具，读的是同一套只读读取器，跑的是同一个运行器，在这台电脑上，或者带上 <code>device</code>，在另一台上。</li></ul><p>只有运行时在 hub 上并且声明了 <code>coding.*</code> 动作的电脑才会出现；手机永远不会。</p><h2 id="what-is-read" tabindex="-1">读的是什么 <a class="header-anchor" href="#what-is-read" aria-label="Permalink to &quot;读的是什么 {#what-is-read}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>助手</th><th>磁盘上的会话</th><th>启动命令</th></tr></thead><tbody><tr><td>Cursor</td><td><code>~/.cursor/projects/&lt;workspace-slug&gt;/agent-transcripts/&lt;id&gt;/&lt;id&gt;.jsonl</code>；CLI 聊天另有 <code>~/.cursor/chats/&lt;hash&gt;/&lt;id&gt;/meta.json</code>（里面的 <code>cwd</code>）</td><td><code>cursor-agent -p --output-format stream-json --stream-partial-output --force [--resume &lt;id&gt;] [--workspace &lt;dir&gt;] &quot;&lt;text&gt;&quot;</code></td></tr><tr><td>Codex</td><td><code>~/.codex/sessions/YYYY/MM/DD/rollout-&lt;time&gt;-&lt;id&gt;.jsonl</code></td><td><code>codex exec [resume &lt;id&gt;] --json --skip-git-repo-check -c sandbox_mode=&quot;workspace-write&quot; [-C &lt;dir&gt;] &quot;&lt;text&gt;&quot;</code></td></tr><tr><td>Claude Code</td><td><code>~/.claude/projects/&lt;workspace-slug&gt;/&lt;id&gt;.jsonl</code></td><td><code>claude -p --output-format stream-json --verbose --permission-mode acceptEdits [--resume &lt;id&gt;] &quot;&lt;text&gt;&quot;</code></td></tr></tbody></table><p>读取是尽力而为：解析不了的一行跳过，目录不存在就当这个助手没有会话。<code>~</code> 是用户的主目录，除非 <code>NANOMUSE_CODING_HOME</code> 指向了别的目录（比如一个把宿主机的 CLI 主目录挂到别处的容器，或者一个测试）。一个会话列出它的助手、id、标题（第一条用户消息）、工作区、时间戳、消息数、最后一轮对话，以及是否 <code>resumable</code>。Cursor 的 IDE 聊天能读但不能从 CLI 续上（<code>resumable: false</code>，<code>source: &quot;ide&quot;</code>）：发给它的消息会直接作为一个新的 CLI 聊天在同一个工作区里发出，引用旧聊天的标题和最后一轮对话，运行结果写明 <code>resumed: false</code>；App 会在输入框上方说明这一点。当一个被存储标为可续的聊天在 CLI 那里查无此号时，走的也是同样的回退。</p><p>助手的 <code>running</code> 是它此刻还活着的进程数，Linux 上读 <code>/proc</code>，macOS 上用 <code>ps</code>，Windows 上用 <code>tasklist</code>（外加 <code>node.exe</code> 的命令行，因为 Cursor CLI 是随 node 打包的）——从不使用 <code>pgrep -f</code>，而且每两秒最多读一次。</p><p>运行器在助手的终止事件到达时就停止读取，而不是等到管道 EOF：<code>cursor-agent</code> 回答完之后会留一个 worker 服务器跑着，否则这次运行会被永远挂住。随后等待该进程，宽限期过后将其杀掉。</p><h2 id="where-it-runs" tabindex="-1">在哪里跑 <a class="header-anchor" href="#where-it-runs" aria-label="Permalink to &quot;在哪里跑 {#where-it-runs}&quot;">​</a></h2><p>每个助手都以它在那台电脑上拥有的权限运行——Codex 在 <code>workspace-write</code> 下，Claude Code 带 <code>acceptEdits</code>，Cursor 带 <code>--force</code>——并且在那里改文件。所以发一条消息被当作在那台电脑上运行一条命令来对待：请求只在同一个账号的设备之间传递，走该账号自己的 hub 会话，而且那台电脑可以完全拒绝远程控制（「远程控制」关掉后，<code>coding.*</code> 只在本机可用）。</p><p>助手自己的 API key 和登录状态是它们自己的；nanoMuse 从不接触。记录是从磁盘读出来给你看的；除了发起请求的那台设备，不会发给任何地方。</p><h2 id="the-api" tabindex="-1">API <a class="header-anchor" href="#the-api" aria-label="Permalink to &quot;API {#the-api}&quot;">​</a></h2><p>在运行时（<code>nanomuse serve</code>）上，需要 App 令牌：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  /api/coding                                  → {agents: [{id, name, installed, cli, version, sessions_root, running}], runs: […]}</span></span>
<span class="line"><span>GET  /api/coding/sessions?agent=&amp;limit=&amp;device=   → {sessions: [{agent, id, title, workspace, path, created_at, updated_at, messages, status, last_user, last_assistant, source, resumable}]}</span></span>
<span class="line"><span>GET  /api/coding/sessions/{agent}/{id}?device=    → the session with transcript: [{role, text}]</span></span>
<span class="line"><span>POST /api/coding/send    {agent, text, session_id?, workspace?, device?, wait?}  → the run</span></span>
<span class="line"><span>POST /api/coding/stop    {run_id, device?}</span></span></code></pre></div><p>一次运行是 <code>{id, agent, session_id, asked_session_id, workspace, text, started_at, ended_at, status, output, resumed, error, tools, device?}</code>；<code>status</code> 是 <code>running</code>、<code>done</code>、<code>error</code> 或 <code>stopped</code> 之一。最近 50 次已结束的运行保存在 <code>&lt;data_dir&gt;/coding/runs.json</code>，运行时启动时读回来，所以记录能挺过重启；当时还在跑的运行回来时变成 <code>stopped</code>，并附一句说明（CLI 进程随运行时一起结束了）。运行期间，总线上传递 <code>{&quot;kind&quot;: &quot;coding&quot;, &quot;run&quot;: id, …}</code> 事件，每个打开的 App 都实时跟着：<code>started {session_id, model}</code>、<code>text {text, partial}</code>（Cursor 先发增量，再发整条消息；App 用最终那条替换掉流式显示的文字）、<code>tool {text, phase}</code>、<code>done</code>、<code>error</code>。</p><h2 id="over-the-hub" tabindex="-1">经由 hub <a class="header-anchor" href="#over-the-hub" aria-label="Permalink to &quot;经由 hub {#over-the-hub}&quot;">​</a></h2><p><code>device</code> 指定另一台电脑；同样的请求以 hub 动作传递（<code>coding.agents</code>、<code>coding.sessions</code>、<code>coding.session</code>、<code>coding.send</code>、<code>coding.stop</code>、<code>coding.runs</code>——见 <a href="./hub">hub.md</a>）。带 <code>wait</code> 的 <code>coding.send</code> 跟着目标机总线上的这次运行，把每一步作为 <code>event</code> 帧转发，帧体带运行 id，所以调用方可以 <code>coding.stop</code> 它；<code>result</code> 帧是结束后的运行。</p><p>测试在 <code>tests/test_coding.py</code>（基于固定记录样本的读取器、流规范化、一个假 CLI、API），hub 这条路径在 <code>tests/test_hub.py</code>。</p>`,21)])])}const g=o(a,[["render",c]]);export{h as __pageData,g as default};
